import sys, json, math, random
W='/home/claude/e15/reviews/31633cd4b8/work'
sys.path[:0]=[W+'/src',W+'/provided']
from e15store.store import RecordStore
from e15store.embedder import tokens, embed
from vretrieval import Retriever
fx=json.load(open(W+'/provided/fixture.json'))
s=RecordStore.from_fixture(W+'/provided/fixture.json'); r=Retriever(s)
def ref(q,p,k):
    vs=r.visible_set(p)
    docs=[d for d in s.current_records() if d['state']=='active' and d['tenant']==vs.tenant and d['acl_group'] in vs.groups]
    if not docs: return []
    qt=list(dict.fromkeys(tokens(q)))
    if not qt: return []
    toks={d['id']:tokens(d['title']+' '+d['body']) for d in docs}
    N=len(docs); avg=sum(map(len,toks.values()))/N
    bm={}
    for t in qt:
        df=sum(1 for v in toks.values() if t in v)
        if not df: continue
        idf=math.log(1+(N-df+.5)/(df+.5))
        for i,v in toks.items():
            tf=v.count(t)
            if tf: bm[i]=bm.get(i,0)+idf*tf*2.2/(tf+1.2*(.25+.75*len(v)/avg))
    qv=embed(q); de={}
    for d in docs:
        c=sum(a*b for a,b in zip(qv,embed(d['title']+'\n'+d['body'])))
        if c>=0.2: de[d['id']]=c
    f={}
    for ch in (bm,de):
        for rank,(i,_) in enumerate(sorted(ch.items(),key=lambda x:(-x[1],x[0]))[:200],1): f[i]=f.get(i,0)+1/(60+rank)
    return [(i,round(v,12)) for i,v in sorted(f.items(),key=lambda x:(-x[1],x[0]))[:k]]
words=sorted({w for d in s.current_records() for w in tokens(d['title']+' '+d['body'])})
random.seed(1); bad=0
qs=['belt slipping','the','a','member health','invoice']+[' '.join(random.sample(words,random.randint(1,4))) for _ in range(150)]
for p in [x['id'] for x in fx['principals']]:
    for q in qs:
        got=[(h.id,round(h.score,12)) for h in r.search(q,p,k=20)]
        exp=ref(q,p,20)
        if got!=exp:
            bad+=1
            if bad<5: print(p,q,got[:6],exp[:6])
print('mismatches',bad)
EOF
